#!/usr/bin/env node
/**
 * Regenerates src/vendor/rnnoise-* from the @sapphi-red/web-noise-suppressor
 * devDependency.
 *
 * The RNNoise worklet and wasm must otherwise be served as static files.
 * Inlining them lets the provider create a blob URL at runtime, so consumers
 * need no asset setup. Only the non-SIMD wasm is shipped (runs everywhere).
 *
 *   node scripts/vendor-rnnoise.mjs
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

// The package does not export ./package.json, so resolve it from node_modules.
const here = dirname(fileURLToPath(import.meta.url));
const pkgDir = join(here, "..", "node_modules", "@sapphi-red", "web-noise-suppressor");
const pkg = JSON.parse(readFileSync(join(pkgDir, "package.json"), "utf8"));
const license = readFileSync(join(pkgDir, "LICENSE"), "utf8").trim();
const outDir = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "vendor");
mkdirSync(outDir, { recursive: true });

const header = (what) =>
  `/*!\n * ${what}\n * Vendored from @sapphi-red/web-noise-suppressor@${pkg.version} (https://github.com/sapphi-red/web-noise-suppressor),\n * which builds xiph/rnnoise (BSD-3-Clause) via shiguredo/rnnoise-wasm.\n * Generated by scripts/vendor-rnnoise.mjs — do not edit by hand.\n *\n${license
    .split("\n")
    .map((l) => ` * ${l}`.trimEnd())
    .join("\n")}\n */\n`;

const worklet = readFileSync(join(pkgDir, "dist", "rnnoise", "workletProcessor.js"), "utf8")
  .replace(/\n\/\/# sourceMappingURL=.*$/m, "");
writeFileSync(
  join(outDir, "rnnoise-worklet-source.ts"),
  `${header("RNNoise AudioWorklet processor source, registered via a blob URL.")}export const RNNOISE_WORKLET_SOURCE: string = ${JSON.stringify(worklet.trim())};\n`,
);

const wasm = readFileSync(join(pkgDir, "dist", "rnnoise.wasm"));
writeFileSync(
  join(outDir, "rnnoise-wasm.ts"),
  `${header("RNNoise wasm binary (rnnoise.wasm), base64.")}export const RNNOISE_WASM_BYTES = ${wasm.length};\nexport const RNNOISE_WASM_BASE64: string =\n  ${JSON.stringify(wasm.toString("base64"))};\n`,
);

console.log(`Vendored @sapphi-red/web-noise-suppressor@${pkg.version} into ${outDir}`);
